// Webhook input is inside $json.body.
// Gmail Trigger input is directly inside $json.
const input =
  $json.body &&
  typeof $json.body === 'object' &&
  !Array.isArray($json.body)
    ? $json.body
    : $json;

const h = input.headers || {};

const getHeader = (name) => {
  const directValue =
    input[name] ??
    input[name.toLowerCase()] ??
    input[name.toUpperCase()];

  if (directValue) {
    return directValue;
  }

  const found = Object.entries(h).find(
    ([key]) => key.toLowerCase() === name.toLowerCase()
  );

  return found ? found[1] : '';
};

const fromRaw = String(
  input.From ||
  input.from ||
  getHeader('From') ||
  ''
);

const subject = String(
  input.Subject ||
  input.subject ||
  getHeader('Subject') ||
  ''
);

const emailMatch =
  fromRaw.match(/<([^>]+)>/) ||
  fromRaw.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);

const customerEmail = emailMatch
  ? emailMatch[1] || emailMatch[0]
  : '';

const customerName = fromRaw
  .replace(/<[^>]+>/, '')
  .replace(/["']/g, '')
  .trim();

const emailBody =
  input.textPlain ||
  input.text ||
  input.snippet ||
  input.email_body ||
  '';

return [
  {
    json: {
      message_id:
        input.id ||
        input.messageId ||
        input.message_id ||
        '',
      thread_id:
        input.threadId ||
        input.thread_id ||
        '',
      customer_email: customerEmail.trim(),
      customer_name: customerName,
      subject: subject.trim(),
      email_body: String(emailBody).trim(),
      received_at:
        input.received_at ||
        new Date().toISOString(),
      source: $json.body ? 'Postman Webhook' : 'Gmail'
    }
  }
];

const src = $('Extract Deterministic Fields').first().json;

// Read Gemini's actual nested response format
let ai =
  $json.content?.parts?.[0]?.text ??
  $json.message?.content ??
  $json.output ??
  $json.text ??
  $json.response ??
  $json;

// Parse JSON string returned by Gemini
if (typeof ai === 'string') {
  const cleaned = ai
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    ai = JSON.parse(cleaned);
  } catch (error) {
    ai = null;
  }
}

// Safe fallback when Gemini output cannot be parsed
if (
  !ai ||
  typeof ai !== 'object' ||
  Array.isArray(ai) ||
  !ai.category
) {
  return [
    {
      json: {
        ...src,
        category: 'general_support',
        priority: 'normal',
        sentiment: 'neutral',
        order_number: src.extracted_order_number || '',
        confidence: 0,
        escalate: true,
        summary: 'Gemini response could not be parsed',
        draft_reply:
          'Thanks for contacting us. A support team member will review your message shortly.',
        raw_ai_output: $json
      }
    }
  ];
}

// Normalize allowed values
const allowedCategories = [
  'order_status',
  'refund_request',
  'damaged_item',
  'cancellation',
  'product_question',
  'complaint',
  'spam',
  'general_support'
];

const allowedPriorities = [
  'low',
  'normal',
  'high',
  'urgent'
];

const category = String(
  ai.category || 'general_support'
).trim().toLowerCase();

const priority = String(
  ai.priority || 'normal'
).trim().toLowerCase();

const sentiment = String(
  ai.sentiment || 'neutral'
).trim().toLowerCase();

let confidence = Number(ai.confidence ?? 0);

if (!Number.isFinite(confidence)) {
  confidence = 0;
}

confidence = Math.max(0, Math.min(1, confidence));

return [
  {
    json: {
      ...src,

      category: allowedCategories.includes(category)
        ? category
        : 'general_support',

      priority: allowedPriorities.includes(priority)
        ? priority
        : 'normal',

      sentiment: ['positive', 'neutral', 'negative'].includes(sentiment)
        ? sentiment
        : 'neutral',

      // Regex result is the only source of truth
      order_number: String(
        src.extracted_order_number || ''
      ).trim(),

      confidence,

      escalate:
        ai.escalate === true ||
        String(ai.escalate).toLowerCase() === 'true',

      summary: String(
        ai.summary || ''
      ).trim(),

      draft_reply: String(
        ai.draft_reply || ''
      ).trim(),

      extracted_email: src.extracted_email || '',
      extracted_phone: src.extracted_phone || '',
      extracted_tracking_id: src.extracted_tracking_id || '',
      extracted_quantity: src.extracted_quantity ?? '',
      extracted_amount: src.extracted_amount || ''
    }
  }
];

const ticket = $('Parse AI Result').first().json;
const orderNo = String(ticket.order_number || '').trim().toLowerCase();
const rows = $input.all().map(i => i.json);
const customerEmail = String(ticket.customer_email || '').trim().toLowerCase();

const order = rows.find(r => {
  const rowOrder = String(
    r['Order Number'] ?? r.order_number ?? r.OrderID ?? ''
  ).trim().toLowerCase();

  const rowEmail = String(
    r['Customer Email'] ?? r.customer_email ?? ''
  ).trim().toLowerCase();

  return rowOrder === orderNo && rowEmail === customerEmail;
});
if (!order) {
  return [{json:{...ticket,order_found:false,escalate:true,final_reply:`Thanks for reaching out. I couldn't verify order ${ticket.order_number} in our records, so I've forwarded this to our support team for review.`}}];
}
const status = order.Status ?? order.status ?? 'Processing';
const tracking = order['Tracking Link'] ?? order.tracking_link ?? '';
const eta = order['Estimated Delivery'] ?? order.estimated_delivery ?? '';
let reply = `Thanks for reaching out. I checked order ${ticket.order_number}. Its current status is ${status}.`;
if (eta) reply += ` The estimated delivery is ${eta}.`;
if (tracking) reply += ` You can track it here: ${tracking}`;
reply += ` Please reply to this email if you need any more help.`;
return [{json:{...ticket,order_found:true,verified_order_status:status,tracking_link:tracking,estimated_delivery:eta,final_reply:reply,escalate:Boolean(ticket.escalate)}}];

const t = $json;

const confidence = Number(t.confidence || 0);

const lowConfidence = confidence < 0.75;

const riskyCategories = [
  'refund_request',
  'damaged_item',
  'cancellation',
  'complaint'
];

const risky = riskyCategories.includes(t.category);

// Order status request contains no order number
const missingOrderNumber =
  t.category === 'order_status' &&
  !String(t.order_number || '').trim();

// Order lookup ran but no matching order was found
const orderNotFound =
  t.category === 'order_status' &&
  t.order_found === false;

const mustEscalate =
  Boolean(t.escalate) ||
  lowConfidence ||
  risky ||
  missingOrderNumber ||
  orderNotFound;

let escalationReason = '';

if (orderNotFound) {
  escalationReason =
    'The order number and customer email could not be verified.';
} else if (missingOrderNumber) {
  escalationReason =
    'The customer requested an order update but did not provide an order number.';
} else if (risky) {
  escalationReason =
    `The ${t.category} request requires human approval.`;
} else if (lowConfidence) {
  escalationReason =
    `AI confidence was below the required threshold: ${confidence}.`;
} else if (Boolean(t.escalate)) {
  escalationReason =
    t.summary || 'The AI marked this request for human review.';
}

const finalReply =
  t.final_reply ||
  t.draft_reply ||
  'Thanks for contacting us. A support team member will review your message shortly.';

return [
  {
    json: {
      ...t,
      must_escalate: mustEscalate,
      escalation_reason: escalationReason,
      final_reply: finalReply,
      status: mustEscalate
        ? 'Escalated'
        : 'Auto Replied',
      processed_at: new Date().toISOString()
    }
  }
];

const subject = String($json.subject || '');
const body = String($json.email_body || '');
const fullText = `${subject}\n${body}`;

// Supports:
// ORD-1002
// ORD-TEST-101
// ORD-US-2026-1001
const orderMatch = fullText.match(
  /\bORD(?:-[A-Z0-9]+)+\b/i
);

const emailMatch = fullText.match(
  /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i
);

const phoneMatch = fullText.match(
  /(?:\+?1[\s.-]?)?(?:\(\d{3}\)|\d{3})[\s.-]?\d{3}[\s.-]?\d{4}\b/
);

const trackingMatch =
  fullText.match(/\b(?:TRK|TRACK)-[A-Z0-9-]+\b/i) ||
  fullText.match(/\b1Z[A-Z0-9]{16}\b/i);

const quantityMatch =
  fullText.match(/\bquantity\s*[:\-]?\s*(\d+)\b/i) ||
  fullText.match(/\b(\d+)\s*(?:items?|units?|pieces?)\b/i);

const amountMatch =
  fullText.match(/\$\s?\d+(?:\.\d{1,2})?/) ||
  fullText.match(/\b\d+(?:\.\d{1,2})?\s?USD\b/i);

return [
  {
    json: {
      ...$json,

      extracted_order_number: orderMatch
        ? orderMatch[0].toUpperCase()
        : '',

      extracted_email: emailMatch
        ? emailMatch[0].toLowerCase()
        : '',

      extracted_phone: phoneMatch
        ? phoneMatch[0].trim()
        : '',

      extracted_tracking_id: trackingMatch
        ? trackingMatch[0].toUpperCase()
        : '',

      extracted_quantity: quantityMatch
        ? Number(quantityMatch[1])
        : '',

      extracted_amount: amountMatch
        ? amountMatch[0].trim()
        : ''
    }
  }
];
